    {
      "part": "head",
      "looks_like": "broad, rounded feline head with a short muzzle, pinkish-brown nose, white fur around the mouth and chin, long white whiskers, dark eyes with light fur underneath, and faint dark stripes on the forehead and cheeks",
      "where": "at the front of the body, turned slightly to face the viewer"
    },
    {
      "part": "ears",
      "looks_like": "two small, rounded, furry ears with light tawny fur on the edges and dark patches on the backs",
      "where": "on top of the head, one on each side"
    },
    {
      "part": "mane",
      "looks_like": "longer, shaggy, tawny fur with lighter and darker strands forming a thick ruff",
      "where": "around the neck, throat, and upper chest, extending from behind the ears down the front"
    },
    {
      "part": "legs",
      "looks_like": "four thick, muscular legs covered in tawny fur with distinct dark horizontal stripes, especially prominent on the lower portions of the hind legs",
      "where": "two front legs under the chest standing vertically, two hind legs at the rear with bent joints in a standing stride"
    },
    {
      "part": "feet",
      "looks_like": "four large, rounded paws with thick toes, light-colored fur, and visible dark claws and pads",
      "where": "at the ends of each leg, front paws viewed from the front and slightly above, hind paws viewed from the side resting on the ground"
    },
    {
      "part": "tail",
      "looks_like": "short, furry tail with tawny fur, faint dark rings, and a dark blackish tuft at the tip",
      "where": "at the rear of the body, extending to the left behind the hind legs"
